const canonicalNameSet=new Set(Object.values(canonicalCatalog).flat().map(n=>n.toLocaleLowerCase('vi-VN').trim()));
// Migrate legacy four-category names for display only; server-side category saved via SQL 037.
// Explicit category wins for the six officially curated groups.
const normalizedCategory=(p:Product):Product=>{
 const n=p.name.toLocaleLowerCase('vi-VN').trim();
 for(const [category,names] of Object.entries(canonicalCatalog)) {
  if(names.some(name=>name.toLocaleLowerCase('vi-VN')===n))return {...p,category};
 }
 if(categoryInfo.some(c=>c.name===p.category)) return p;
 let category='Tắm & Chăm sóc lông';
 if(/hộp đựng thức ăn|muỗng đong|máy cho ăn|bát ăn|bát inox|bát sứ|khay ăn|bát nhựa|thảm lót|bình nước tự động|đệm|nệm|nhà ngủ|chăn mềm/.test(n))category='Dụng cụ ăn uống & Nghỉ ngơi';
 else if(/hạt|pate|pa-tê|súp thưởng|snack|bánh thưởng|bánh quy|pudding|thức ăn|combo pate/.test(n))category='Thức ăn & Dinh dưỡng';
 else if(/bàn chải đánh răng|kem đánh răng|vệ sinh|khăn ướt|khăn lau|cát|xẻng|tấm lót|lót khay|túi đựng phân|túi cuộn|rửa bát|lau chân|khử mùi khay|vệ sinh tai/.test(n))category='Vệ sinh & Răng miệng';
 else if(/đồ chơi|bóng|cần câu|chuột bông|dây thừng|kéo co|đĩa bay|thú bông|gặm|bàn cào/.test(n))category='Đồ chơi & Vận động';
 else if(/dây dắt|vòng cổ|yếm ngực|balo|túi vận chuyển|túi đựng đồ|túi xách|bình nước du lịch|bình nước cầm tay|bát du lịch|bát gấp|đai an toàn/.test(n))category='Đi dạo & Di chuyển';
 return {...p,category};
};
// Only switch to the 90-item presentation once the TEST database contains the full set.
// Before SQL 037, continue showing existing records rather than leaving the shop empty.
const storefrontCatalog=(items:Product[]):Product[]=>{
 const canonical=items.filter(p=>canonicalNameSet.has(p.name.toLocaleLowerCase('vi-VN').trim()));
 const complete=Object.entries(canonicalCatalog).every(([cat,names])=>names.every(n=>canonical.some(p=>p.category===cat&&p.name.toLocaleLowerCase('vi-VN').trim()===n.toLocaleLowerCase('vi-VN'))));
 if(!complete)return items;
 const unique=new Set<string>();
 return canonical.filter(p=>{const k=p.name.toLocaleLowerCase('vi-VN').trim();if(unique.has(k))return false;unique.add(k);return true});
};
export function AdminServicePrices({token}:{token:string}){
 const [items,setItems]=useState<{name:string;basePrice:number;category:string;duration:number;active:boolean}[]>([]);const [draft,setDraft]=useState<Record<string,number>>({});const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [checkoutAttempted,setCheckoutAttempted]=useState(false);
 const load=async()=>{try{const data=await request('/admin/services/prices',token);setItems(data);setDraft(Object.fromEntries(data.map((x:any)=>[x.name,x.basePrice])))}catch(e){setError(String(e))}};
 useEffect(()=>{load()},[token]);
 async function setAvailable(name:string,active:boolean){setBusy(true);setError('');setNotice('');try{await request('/admin/services/'+encodeURIComponent(name)+'/availability',token,'PATCH',{active});setNotice(active?'Đã mở nhận lịch mới cho gói dịch vụ.':'Đã tạm ngừng nhận lịch mới. Lịch đã đặt vẫn giữ nguyên.');await load()}catch(e){setError(String(e))}finally{setBusy(false)}}
 async function save(name:string){setBusy(true);setError('');setNotice('');try{await request('/admin/services/prices/'+encodeURIComponent(name),token,'PUT',{basePrice:draft[name]});setNotice('Đã lưu giá mới vào PostgreSQL. Các lịch cũ giữ nguyên tổng tiền.');await load()}catch(e){setError(String(e))}finally{setBusy(false)}}
 return <details className={panel}><summary className="cursor-pointer font-extrabold text-[#142B55]">Bảng giá dịch vụ · quản lý giá gói</summary><p className="mt-2 text-sm text-slate-600">Điều chỉnh giá và mở/tạm ngừng nhận lịch mới cho 8 gói. Lịch cũ giữ nguyên giá và trạng thái. Tạm ngừng không xóa gói hoặc lịch sử.</p>{error&&<p role="alert" className="mt-3 rounded-lg bg-red-50 p-2 text-red-700">{error}</p>}{notice&&<p role="status" className="mt-3 rounded-lg bg-blue-50 p-2 text-[#142B55]">{notice}</p>}<div className="mt-4 space-y-2">{items.map(x=><div className="grid items-center gap-2 rounded-xl bg-[#F5F8FD] p-3 sm:grid-cols-[1fr_145px_90px_125px]" key={x.name}><div><strong className="text-[#142B55]">{x.name}</strong><p className="text-xs text-slate-500">{x.category} · {x.duration} phút · {x.active?'Đang nhận lịch':'Tạm ngừng'} · Giá đang lưu: {money(x.basePrice)}</p></div><input aria-label={'Giá '+x.name} type="number" min={20000} max={5000000} step={1000} value={draft[x.name]??x.basePrice} onChange={e=>setDraft(v=>({...v,[x.name]:Number(e.target.value)}))} className="rounded-lg border p-2"/><button type="button" disabled={busy||draft[x.name]===x.basePrice} onClick={()=>save(x.name)} className="rounded-lg bg-[#142B55] p-2 font-bold text-white disabled:opacity-40">Lưu giá</button><button type="button" disabled={busy} onClick={()=>setAvailable(x.name,!x.active)} className={'rounded-lg border px-2 py-2 text-xs font-bold '+(x.active?'border-amber-300 text-amber-900':'border-blue-300 text-[#142B55]')}>{x.active?'Tạm ngừng':'Mở nhận lịch'}</button></div>)}</div></details>;
}
export function StandaloneRetailShop({token}:{token:string}){
 const [query,setQuery]=useState('');const [category,setCategory]=useState(()=>{const requested=sessionStorage.getItem('petday_shop_category_prefill');sessionStorage.removeItem('petday_shop_category_prefill');return requested&&categoryInfo.some(c=>c.name===requested)?requested:'Tất cả'});const [sort,setSort]=useState('name');const [inStockOnly,setInStockOnly]=useState(false);const [petType,setPetType]=useState<'all'|'dog'|'cat'>('all');const [priceBand,setPriceBand]=useState('all');const [detail,setDetail]=useState<Product|null>(null);const [page,setPage]=useState(1);
 const [cancelRequests,setCancelRequests]=useState<Record<string,{status:string;reason:string;adminNote?:string}>>({});const [cancelReason,setCancelReason]=useState<Record<string,string>>({});const [cancelOpen,setCancelOpen]=useState<string|null>(null);const [products,setProducts]=useState<Product[]>([]),[orders,setOrders]=useState<Order[]>([]);const [retailRefunds,setRetailRefunds]=useState<{id:number;code:string;amount:number;status:string;adminNote?:string;createdAt?:string;completedAt?:string;orderCreatedAt?:string;refundReference?:string}[]>([]);const [chosen,setChosen]=useState<Record<number,number>>({});
 const [branch,setBranch]=useState('PetDay Thảo Điền');const [method,setMethod]=useState<'cash'|'bank_transfer'>('cash');
 const [fulfillment,setFulfillment]=useState<'pickup'|'delivery'>('pickup');const [deliveryZone,setDeliveryZone]=useState<'inner_hcm'|'outer_hcm'>('inner_hcm');
 const [receiverName,setReceiverName]=useState('');const [receiverPhone,setReceiverPhone]=useState('');const [deliveryAddress,setDeliveryAddress]=useState('');const [deliveryNote,setDeliveryNote]=useState('');
 const [transferNotices,setTransferNotices]=useState<Record<string,boolean>>({});const [openTransfer,setOpenTransfer]=useState<string|null>(null);const [reportBusy,setReportBusy]=useState('');const [bankEnabled,setBankEnabled]=useState(false);const [recipient,setRecipient]=useState<{bankName:string;accountNumber:string;accountHolder:string}|null>(null);const [error,setError]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [checkoutAttempted,setCheckoutAttempted]=useState(false);
 const load=async()=>{try{const [p,o]=await Promise.all([request('/retail/products',token),request('/my/retail-orders',token)]);setProducts(storefrontCatalog((p as Product[]).map(normalizedCategory)));setOrders(o);const cr=await request('/my/retail/cancellation-requests',token).catch(()=>[]);setCancelRequests(Object.fromEntries((Array.isArray(cr)?cr:[]).map((x:{code:string;status:string;reason:string;adminNote?:string})=>[x.code,x])));const rf=await request('/my/retail/refunds',token).catch(()=>[]);setRetailRefunds(Array.isArray(rf)?rf:[]);const noticeRows=await request('/my/retail-transfer-notices',token).catch(()=>[]);setTransferNotices(Object.fromEntries((Array.isArray(noticeRows)?noticeRows:[]).map((n:{code:string})=>[n.code,true])));const opt=await request('/payment/options',token);setBankEnabled(Boolean(opt.bankTransfer?.enabled));setRecipient(opt.bankTransfer?.enabled?{bankName:opt.bankTransfer.bankName,accountNumber:opt.bankTransfer.accountNumber,accountHolder:opt.bankTransfer.accountHolder}:null)}catch(e){setError(String(e))}};
 useEffect(()=>{load()},[token]);
 async function reportTransfer(code:string,info:SenderInfo){setReportBusy(code);setError('');try{
  const result=await request('/my/retail-orders/'+encodeURIComponent(code)+'/transfer-notice',token,'POST',info);
  setTransferNotices(v=>({...v,[code]:true}));setOpenTransfer(null);setMessage(result.message||'Đã gửi thông báo chuyển khoản.');
 }catch(e){setError(e instanceof Error?e.message:String(e));throw e}finally{setReportBusy('')}}
 async function sendCancel(code:string){const reason=(cancelReason[code]||'').trim();if(reason.length<10){setError('Vui lòng ghi lý do hủy ít nhất 10 ký tự.');return;}setBusy(true);setError('');try{await request('/my/retail-orders/'+encodeURIComponent(code)+'/cancellation-request',token,'POST',{reason});setCancelOpen(null);setMessage('Đã gửi yêu cầu hủy đơn '+code+'. Chờ Admin xem xét.');await load()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
 const categories=['Tất cả',...categoryInfo.map(c=>c.name)];
 const petCompatibility=(p:Product)=>{const n=(p.name+' '+(p.description||'')).toLocaleLowerCase('vi-VN');const dog=/(cho chó|chó con|chó trưởng|giống chó|vị chó)/.test(n);const cat=/(cho mèo|mèo con|mèo trưởng|cát vệ sinh mèo|khay vệ sinh mèo)/.test(n);return dog&&!cat?'dog':cat&&!dog?'cat':'both'};
 const filtered=products.filter(p=>(!inStockOnly||p.stock>0)&&(category==='Tất cả'||p.category===category)&&(petType==='all'||petCompatibility(p)==='both'||petCompatibility(p)===petType)&&(priceBand==='all'||(priceBand==='under100'?p.price<100000:priceBand==='100to300'?p.price>=100000&&p.price<=300000:p.price>300000))&&`${p.name} ${p.category} ${p.description||''}`.toLocaleLowerCase('vi-VN').includes(query.trim().toLocaleLowerCase('vi-VN'))).sort((a,b)=>sort==='price-asc'?a.price-b.price:sort==='price-desc'?b.price-a.price:a.name.localeCompare(b.name,'vi'));
 const pageSize=9;const totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));const currentPage=Math.min(page,totalPages);const visible=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);
 const selected=products.filter(p=>chosen[p.id]>0);const subtotal=selected.reduce((n,p)=>n+p.price*chosen[p.id],0);const count=selected.reduce((n,p)=>n+chosen[p.id],0);const selectedKinds=selected.length;
 const deliveryFee=fulfillment==='delivery'&&selected.length?deliveryZoneMeta[deliveryZone].fee:0; const grandTotal=subtotal+deliveryFee;
 const categoryCounts=useMemo(()=>Object.fromEntries(categoryInfo.map(item=>[item.name,products.filter(p=>p.category===item.name).length])),[products]);
 function change(p:Product,delta:number){setMessage('');setCheckoutAttempted(false);setChosen(v=>{const old=v[p.id]||0;const next=Math.max(0,Math.min(99,p.stock,old+delta));return {...v,[p.id]:next}})}
 const validReceiverPhone=/^(0\d{9}|\+84\d{9})$/.test(receiverPhone.trim().replace(/[ .-]/g,''));
 const checkoutBlockers=[
  ...(selected.length===0?['Giỏ hàng chưa có sản phẩm.']:[]),
  ...selected.filter(p=>chosen[p.id]<=0||chosen[p.id]>p.stock||chosen[p.id]>99).map(p=>`Sản phẩm “${p.name}”: đã chọn ${chosen[p.id]} nhưng hiện chỉ còn ${Math.max(0,p.stock)} sản phẩm. Hãy giảm số lượng hoặc xóa khỏi giỏ.`),
  ...(fulfillment==='delivery'&&receiverName.trim().length<2?['Vui lòng nhập tên người nhận (ít nhất 2 ký tự).']:[]),
  ...(fulfillment==='delivery'&&!validReceiverPhone?['Số điện thoại cần có 10 chữ số, bắt đầu bằng 0 (hoặc +84 và 9 chữ số).']:[]),
  ...(fulfillment==='delivery'&&deliveryAddress.trim().length<12?['Địa chỉ giao hàng cần ít nhất 12 ký tự và phải ghi rõ số nhà, đường, phường/xã.']:[]),
  ...(method==='bank_transfer'&&!bankEnabled?['Chuyển khoản chưa được mở. Vui lòng chọn thanh toán tiền mặt.']:[])
 ];
 const canSubmit=checkoutBlockers.length===0;
 async function place(){setCheckoutAttempted(true);if(!canSubmit){setError('Chưa thể đặt hàng: '+checkoutBlockers.join(' '));document.getElementById('petday-checkout-errors')?.scrollIntoView({behavior:'smooth',block:'center'});return;}setBusy(true);setError('');setMessage('');try{const order=await request('/retail/orders',token,'POST',{branch,paymentMethod:method,fulfillmentMethod:fulfillment,deliveryZone:fulfillment==='delivery'?deliveryZone:undefined,receiverName:fulfillment==='delivery'?receiverName:undefined,receiverPhone:fulfillment==='delivery'?receiverPhone:undefined,deliveryAddress:fulfillment==='delivery'?deliveryAddress:undefined,deliveryNote:fulfillment==='delivery'?deliveryNote:undefined,items:selected.map(p=>({id:p.id,quantity:chosen[p.id]})),idempotencyKey:crypto.randomUUID()});setChosen({});setCheckoutAttempted(false);setReceiverName('');setReceiverPhone('');setDeliveryAddress('');setDeliveryNote('');setMessage('Đã tạo đơn '+order.code+'. '+(method==='bank_transfer'?'Vui lòng điền thông tin chuyển khoản ngay bên dưới để Admin kiểm tra.':'Nhân viên PetDay sẽ xác nhận đơn hàng và cách nhận.'));if(method==='bank_transfer')setOpenTransfer(order.code);await load();if(method==='bank_transfer'){document.getElementById('petday-purchase-history')?.setAttribute('open','');document.getElementById('petday-purchase-history')?.scrollIntoView({behavior:'smooth',block:'start'})}}catch(e){setError(String(e))}finally{setBusy(false)}}
 return <section className="overflow-hidden rounded-[30px] border border-[#E1E8F3] bg-white shadow-[0_16px_60px_rgba(20,43,85,0.06)]">
  <div className="relative overflow-hidden bg-[#172D55] px-6 py-9 text-white md:px-10 md:py-12"><div className="pointer-events-none absolute -right-10 -top-24 h-72 w-72 rounded-full bg-[#FF7766]/20 blur-2xl"/><div className="pointer-events-none absolute right-24 -bottom-32 h-64 w-64 rounded-full border-[30px] border-white/5"/><div className="relative z-10 max-w-3xl"><span className="rounded-full border border-white/20 bg-white/10 px-3 py-1 text-[11px] font-bold uppercase tracking-[.18em] text-[#FFD6CD]">PetDay • Pet essentials</span><h1 className="mt-5 text-3xl font-black tracking-tight md:text-5xl">Mua sắm tiện lợi,<br/><span className="text-[#FF9C8F]">giao tận nhà hoặc nhận tại cửa hàng.</span></h1><p className="mt-4 max-w-2xl text-sm leading-7 text-[#DBE5F3] md:text-base">Từ thức ăn, vệ sinh, chăm sóc đến phụ kiện: PetDay Shop hỗ trợ mua độc lập, mua kèm dịch vụ, nhận tại chi nhánh hoặc giao tận nơi trong khu vực TP.HCM.</p><div className="mt-6 flex flex-wrap gap-2 text-xs font-semibold"><span className="rounded-full bg-white/10 px-4 py-2">✓ Danh mục rõ ràng</span><span className="rounded-full bg-white/10 px-4 py-2">✓ Hình sản phẩm trực quan</span><span className="rounded-full bg-white/10 px-4 py-2">✓ Nhận tại cửa hàng / giao tận nơi</span></div></div></div>
  <div className="px-4 py-7 md:px-8 md:py-9">{error&&<p role="alert" className="mb-4 rounded-xl bg-red-50 p-4 text-sm text-red-700">{error}</p>}
   <div className="mb-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3" role="group" aria-label="Khám phá danh mục sản phẩm">{categoryInfo.map(item=><button type="button" key={item.name} aria-pressed={category===item.name} onClick={()=>{setCategory(item.name);setPage(1)}} className={'group overflow-hidden rounded-[24px] border text-left transition duration-200 hover:-translate-y-0.5 hover:shadow-lg '+(category===item.name?'border-[#172D55] shadow-[0_8px_24px_rgba(23,45,85,0.14)]':'border-[#E4EBF4] bg-white hover:border-[#FF9D8F]')}><div className="relative h-36 overflow-hidden bg-[#F7F8FC] md:h-40"><img src={item.image} alt={'Sản phẩm thuộc danh mục '+item.name} loading="eager" className="h-full w-full object-cover object-center transition duration-500 group-hover:scale-[1.04]"/><span className="absolute right-3 top-3 rounded-full bg-white/95 px-3 py-1 text-xs font-bold text-[#172D55] shadow-sm">{categoryCounts[item.name]||0} sản phẩm</span></div><div className={'min-h-[96px] px-4 py-3 '+(category===item.name?'bg-[#172D55] text-white':'bg-[#F8FBFF] text-[#172D55]')}><strong className="text-lg font-extrabold">{item.name}</strong><p className={'mt-1 text-xs leading-5 '+(category===item.name?'text-[#E2ECF7]':'text-slate-500')}>{item.blurb}</p></div></button>)}</div>
   <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-[#E57362]">Danh mục chọn lọc</p><h2 className="mt-1 text-2xl font-black text-[#172D55]">Sản phẩm cho thú cưng</h2><p className="mt-1 text-sm text-slate-500">{filtered.length} sản phẩm phù hợp • Chọn sản phẩm tùy thích · Kiểm tra tồn kho khi đặt</p></div><div className="rounded-full bg-[#F4F7FC] px-4 py-2 text-sm font-semibold text-[#172D55]">🛒 {count} món • {money(grandTotal)}</div></div>
   <div className="grid gap-3 md:grid-cols-[1fr_220px]"><label className="flex items-center gap-2 rounded-2xl border border-[#DCE6F2] bg-[#F8FAFE] px-4"><span aria-hidden="true">⌕</span><input aria-label="Tìm sản phẩm" placeholder="Tìm thức ăn, phụ kiện, chăm sóc..." className="w-full bg-transparent py-3 text-sm outline-none" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></label><select aria-label="Sắp xếp theo" className="rounded-2xl border border-[#DCE6F2] bg-white px-4 py-3 text-sm text-[#172D55]" value={sort} onChange={e=>{setSort(e.target.value);setPage(1)}}><option value="name">Tên A–Z</option><option value="price-asc">Giá thấp đến cao</option><option value="price-desc">Giá cao đến thấp</option></select></div>
   <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><label className="grid gap-1 text-xs font-bold text-[#172D55]">Phù hợp với<select aria-label="Lọc theo thú cưng" className="rounded-xl border border-[#DCE6F2] bg-white p-3 text-sm font-normal" value={petType} onChange={e=>{setPetType(e.target.value as 'all'|'dog'|'cat');setPage(1)}}><option value="all">Chó và mèo</option><option value="dog">Dành cho chó</option><option value="cat">Dành cho mèo</option></select></label><label className="grid gap-1 text-xs font-bold text-[#172D55]">Khoảng giá<select aria-label="Lọc theo khoảng giá" className="rounded-xl border border-[#DCE6F2] bg-white p-3 text-sm font-normal" value={priceBand} onChange={e=>{setPriceBand(e.target.value);setPage(1)}}><option value="all">Tất cả mức giá</option><option value="under100">Dưới 100.000đ</option><option value="100to300">100.000đ – 300.000đ</option><option value="over300">Trên 300.000đ</option></select></label><div className="flex items-end"><p className="rounded-xl bg-[#F4F7FC] px-4 py-3 text-xs leading-5 text-[#536582]">Bộ lọc phù hợp dựa trên tên sản phẩm; sản phẩm dùng chung hiển thị ở cả hai loài.</p></div></div>
   <div className="my-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#E1E8F2] bg-[#F8FBFF] px-4 py-3"><label className="flex cursor-pointer items-center gap-2 text-sm font-semibold text-[#172D55]"><input type="checkbox" className="h-4 w-4 accent-[#172D55]" checked={inStockOnly} onChange={e=>{setInStockOnly(e.target.checked);setPage(1)}}/>Chỉ hiện sản phẩm còn hàng</label><button type="button" className="text-sm font-bold text-[#D15F50] hover:underline" onClick={()=>{setCategory('Tất cả');setSort('name');setQuery('');setInStockOnly(false);setPetType('all');setPriceBand('all');setPage(1)}}>Xóa bộ lọc</button></div><div className="my-5 flex flex-wrap gap-2" role="group" aria-label="Lọc danh mục">{categories.map(c=><button key={c} type="button" onClick={()=>{setCategory(c);setPage(1)}} className={'rounded-full px-5 py-2.5 text-sm font-bold transition '+(category===c?'bg-[#172D55] text-white shadow-md':'border border-[#E1E8F2] bg-white text-[#536582] hover:bg-[#F4F7FC]')}>{c==='Tất cả'?'Tất cả sản phẩm':c}</button>)}</div>
   {visible.length===0?<div className="rounded-2xl bg-[#F7FAFD] p-12 text-center text-slate-500">Không có sản phẩm phù hợp. Hãy thử từ khóa hoặc danh mục khác.</div>:<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{visible.map(p=><article key={p.id} className={'group flex flex-col overflow-hidden rounded-[22px] border bg-white shadow-[0_8px_30px_rgba(20,43,85,0.045)] transition hover:-translate-y-1 hover:shadow-[0_18px_36px_rgba(20,43,85,0.1)] '+(chosen[p.id]?'border-[#FF8676]':'border-[#E5EBF4]')}><div className={'relative h-48 overflow-hidden bg-gradient-to-br '+categoryTone(p.category)}><img src={productImage(p.name,p.category)} alt={p.name} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" loading="lazy" onError={e=>{const fallback=categoryFallback(p.category);if(!e.currentTarget.src.endsWith(fallback)){e.currentTarget.src=fallback;}}}/><div className="absolute inset-x-0 bottom-0 h-24 bg-gradient-to-t from-[#0F1831]/45 to-transparent"/><span className="absolute left-4 top-4 rounded-full bg-white/95 px-3 py-1 text-[11px] font-bold text-[#172D55] shadow-sm">{p.category}</span>{Boolean(chosen[p.id])&&<span className="absolute right-4 top-4 rounded-full bg-[#172D55] px-3 py-1 text-[11px] font-bold text-white">Đã chọn</span>}</div><div className="flex flex-1 flex-col p-5"><button type="button" onClick={()=>setDetail(p)} className="min-h-12 text-left text-base font-extrabold leading-6 text-[#172D55] hover:text-[#D45B49] focus-visible:underline">{p.name}</button><p className="mt-2 min-h-10 text-sm leading-5 text-slate-500">{p.description||'Sản phẩm dành cho thú cưng, được chọn lọc theo nhu cầu hằng ngày.'}</p><button type="button" onClick={()=>setDetail(p)} className="mt-2 w-fit text-xs font-bold text-[#D45B49] hover:underline">Xem chi tiết →</button><p className={'mt-2 text-xs font-semibold '+(p.stock?'text-[#718198]':'text-red-600')}>{p.stock?'● Còn '+p.stock+' sản phẩm':'● Tạm hết hàng'}</p><div className="mt-auto flex items-center justify-between gap-2 pt-5"><strong className="text-xl font-black text-[#172D55]">{money(p.price)}</strong><div className="flex items-center gap-2"><button type="button" aria-label={'Giảm '+p.name} className="h-9 w-9 rounded-xl border border-[#DBE3EF] bg-white font-bold text-[#172D55] disabled:opacity-30" disabled={!chosen[p.id]} onClick={()=>change(p,-1)}>−</button><span className="w-4 text-center text-sm font-extrabold">{chosen[p.id]||0}</span><button type="button" aria-label={'Thêm '+p.name} className="h-9 w-9 rounded-xl bg-[#FF7666] font-bold text-white disabled:opacity-30" disabled={(chosen[p.id]||0)>=Math.min(99,p.stock)} onClick={()=>change(p,1)}>+</button></div></div></div></article>)}</div>}
   {detail&&<div className="fixed inset-0 z-[120] flex items-center justify-center bg-[#07152D]/60 p-4" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setDetail(null)}}><section role="dialog" aria-modal="true" aria-labelledby="petday-product-detail-title" className="relative w-full max-w-3xl overflow-hidden rounded-[28px] bg-white shadow-2xl"><button type="button" aria-label="Đóng chi tiết sản phẩm" className="absolute right-4 top-4 z-10 rounded-full bg-white px-3 py-2 text-lg font-bold shadow" onClick={()=>setDetail(null)}>✕</button><div className="grid md:grid-cols-2"><img src={productImage(detail.name,detail.category)} alt={detail.name} className="h-64 w-full bg-[#F6F8FC] object-contain p-3 md:h-full" onError={e=>{e.currentTarget.src=categoryFallback(detail.category)}}/><div className="space-y-4 p-6 md:p-8"><p className="text-xs font-bold uppercase tracking-wider text-[#E57362]">{detail.category}</p><h3 id="petday-product-detail-title" className="text-2xl font-black text-[#172D55]">{detail.name}</h3><p className="text-sm leading-7 text-slate-600">{detail.description||'Sản phẩm tiện ích dành cho thú cưng.'}</p><p className="text-2xl font-black text-[#172D55]">{money(detail.price)}</p><p className="text-sm text-slate-600">{detail.stock>0?`Còn ${detail.stock} sản phẩm`:'Tạm hết hàng'} · Giá và tồn kho được kiểm tra lại khi đặt.</p><div className="flex items-center gap-3"><button className="rounded-xl border px-4 py-2 disabled:opacity-30" disabled={!chosen[detail.id]} onClick={()=>change(detail,-1)}>−</button><span className="font-bold">{chosen[detail.id]||0}</span><button className="rounded-xl bg-[#FF7666] px-4 py-2 font-bold text-white disabled:opacity-30" disabled={(chosen[detail.id]||0)>=Math.min(99,detail.stock)} onClick={()=>change(detail,1)}>+ Thêm vào giỏ</button></div><button type="button" onClick={()=>{setDetail(null);document.getElementById('petday-cart-checkout')?.scrollIntoView({behavior:'smooth'})}} className="w-full rounded-xl bg-[#172D55] px-4 py-3 font-bold text-white">Xem giỏ hàng và thanh toán</button></div></div></section></div>}
   {totalPages>1&&<nav aria-label="Trang sản phẩm" className="mt-6 flex items-center justify-center gap-3"><button type="button" disabled={currentPage<=1} onClick={()=>setPage(p=>Math.max(1,p-1))} className="rounded-xl border px-4 py-2 text-sm disabled:opacity-30">← Trước</button><span className="text-sm font-semibold text-[#172D55]">{currentPage} / {totalPages}</span><button type="button" disabled={currentPage>=totalPages} onClick={()=>setPage(p=>Math.min(totalPages,p+1))} className="rounded-xl border px-4 py-2 text-sm disabled:opacity-30">Sau →</button></nav>}
   <div id="petday-cart-checkout" className="mt-10 grid scroll-mt-24 gap-5 lg:grid-cols-[1fr_1.12fr]">
    <div className="rounded-[24px] border border-[#E3EAF4] bg-[#F7F9FD] p-6"><div className="flex items-center justify-between gap-3"><h3 className="text-xl font-black text-[#172D55]">Giỏ hàng của bạn</h3><span className="rounded-full bg-white px-3 py-1 text-xs font-bold text-[#172D55]">{count} sản phẩm</span></div>{selected.length?<div className="mt-5 space-y-3">{selected.map(p=><div key={p.id} className="flex items-start justify-between gap-3 rounded-xl bg-white p-3 text-sm"><span className="flex-1 font-medium text-[#172D55]">{p.name}<span className="mt-1 block text-xs text-slate-500">{p.category}</span><span className="mt-2 flex items-center gap-2"><button type="button" aria-label={'Giảm số lượng '+p.name} className="rounded-lg border px-2.5 py-1" onClick={()=>change(p,-1)}>−</button><span className="font-bold">{chosen[p.id]}</span><button type="button" aria-label={'Tăng số lượng '+p.name} className="rounded-lg border px-2.5 py-1 disabled:opacity-30" disabled={chosen[p.id]>=Math.min(99,p.stock)} onClick={()=>change(p,1)}>+</button><button type="button" className="ml-2 text-xs font-semibold text-[#C55245] underline" onClick={()=>setChosen(v=>({...v,[p.id]:0}))}>Xóa</button></span></span><strong className="shrink-0 text-[#172D55]">{money(p.price*chosen[p.id])}</strong></div>)}</div>:<div className="mt-5 rounded-2xl border border-dashed border-[#CFDBE9] p-8 text-center"><span className="text-4xl">🛒</span><p className="mt-2 text-sm text-slate-500">Chưa có sản phẩm nào. Chọn dấu + trên thẻ sản phẩm để thêm vào giỏ.</p></div>}<div className="mt-5 space-y-3 border-t pt-4 text-sm"><div className="flex items-center justify-between"><span className="font-semibold text-slate-600">Tạm tính sản phẩm</span><strong className="text-[#172D55]">{money(subtotal)}</strong></div>{fulfillment==='delivery'&&<div className="flex items-center justify-between"><span className="font-semibold text-slate-600">Phí giao hàng</span><strong className="text-[#172D55]">{money(deliveryFee)}</strong></div>}<div className="flex items-center justify-between border-t pt-3"><span className="font-semibold text-slate-700">Tổng dự kiến</span><strong className="text-2xl font-black text-[#172D55]">{money(grandTotal)}</strong></div></div></div>
    <div className="rounded-[24px] border border-[#E3EAF4] bg-white p-6"><h3 className="text-xl font-black text-[#172D55]">Thông tin nhận hàng</h3><p className="mt-1 text-sm text-slate-500">Khách có thể chọn nhận tại chi nhánh hoặc giao tận nhà. Phí giao hàng là mức ước tính theo khu vực, nhân viên xác nhận lại trước khi xử lý đơn.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={()=>setFulfillment('pickup')} className={'rounded-2xl border p-4 text-left transition '+(fulfillment==='pickup'?'border-[#172D55] bg-[#172D55] text-white':'border-[#DCE6F2] bg-[#F8FBFF] text-[#172D55]')}><strong>Nhận tại cửa hàng</strong><p className={'mt-1 text-xs '+(fulfillment==='pickup'?'text-white/80':'text-slate-500')}>Khách đến nhận tại chi nhánh PetDay.</p></button><button type="button" onClick={()=>setFulfillment('delivery')} className={'rounded-2xl border p-4 text-left transition '+(fulfillment==='delivery'?'border-[#FF7666] bg-[#FFF2EE] text-[#172D55]':'border-[#DCE6F2] bg-[#F8FBFF] text-[#172D55]')}><strong>Giao tận nhà</strong><p className="mt-1 text-xs text-slate-500">Giao trong TP.HCM, phí ship theo khu vực.</p></button></div><label className="mt-5 block text-sm font-semibold text-[#172D55]">Chi nhánh xử lý đơn<select value={branch} onChange={e=>setBranch(e.target.value)} className="mt-2 w-full rounded-xl border border-[#DCE6F2] bg-white p-3"><option>PetDay Thảo Điền</option><option>PetDay Phú Mỹ Hưng</option></select></label>{fulfillment==='delivery'&&<><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="block text-sm font-semibold text-[#172D55]">Người nhận<input className="mt-2 w-full rounded-xl border border-[#DCE6F2] bg-white p-3" value={receiverName} onChange={e=>setReceiverName(e.target.value)} placeholder="Họ tên người nhận"/></label><label className="block text-sm font-semibold text-[#172D55]">Số điện thoại<input className="mt-2 w-full rounded-xl border border-[#DCE6F2] bg-white p-3" value={receiverPhone} onChange={e=>setReceiverPhone(e.target.value)} placeholder="09xxxxxxxx (10 chữ số)" inputMode="tel"/></label></div><label className="mt-4 block text-sm font-semibold text-[#172D55]">Khu vực giao hàng<select value={deliveryZone} onChange={e=>setDeliveryZone(e.target.value as 'inner_hcm'|'outer_hcm')} className="mt-2 w-full rounded-xl border border-[#DCE6F2] bg-white p-3">{Object.entries(deliveryZoneMeta).map(([value,meta])=><option key={value} value={value}>{meta.label} · {money(meta.fee)}</option>)}</select></label><label className="mt-4 block text-sm font-semibold text-[#172D55]">Địa chỉ giao hàng<input className="mt-2 w-full rounded-xl border border-[#DCE6F2] bg-white p-3" value={deliveryAddress} onChange={e=>setDeliveryAddress(e.target.value)} placeholder="Số nhà, đường, phường/xã, quận/huyện"/></label><label className="mt-4 block text-sm font-semibold text-[#172D55]">Ghi chú giao hàng (không bắt buộc)<textarea className="mt-2 min-h-[92px] w-full rounded-xl border border-[#DCE6F2] bg-white p-3" value={deliveryNote} onChange={e=>setDeliveryNote(e.target.value)} placeholder="Ví dụ: gọi trước khi giao, giao giờ hành chính..."/></label></>}
    <fieldset className="mt-5 space-y-3"><legend className="text-base font-extrabold text-[#172D55]">Phương thức thanh toán</legend><p className="text-xs text-[#64758F]">Chọn một phương thức cho đơn mua hàng. Trạng thái thanh toán và giao/nhận được theo dõi độc lập.</p><div className="grid gap-3 sm:grid-cols-2"><label className={'flex cursor-pointer items-start gap-3 rounded-2xl border-2 p-4 transition '+(method==='cash'?'border-[#172D55] bg-[#F0F5FC] shadow-sm':'border-[#E0E7F2] bg-white hover:border-[#91AACB]')}><input type="radio" name="retail-payment-method" className="mt-1 accent-[#172D55]" checked={method==='cash'} onChange={()=>setMethod('cash')}/><span><strong className="block text-sm text-[#172D55]">Tiền mặt</strong><span className="mt-1 block text-xs leading-5 text-slate-600">{fulfillment==='pickup'?'Thanh toán tại quầy khi nhận sản phẩm':'Thanh toán khi nhận hàng tại nhà'}</span></span></label><label className={'flex items-start gap-3 rounded-2xl border-2 p-4 transition '+(!bankEnabled?'cursor-not-allowed border-[#EDF0F4] bg-[#F7F8FA] text-slate-400':method==='bank_transfer'?'cursor-pointer border-[#172D55] bg-[#F0F5FC] shadow-sm':'cursor-pointer border-[#E0E7F2] bg-white hover:border-[#91AACB]')}><input type="radio" name="retail-payment-method" className="mt-1 accent-[#172D55]" disabled={!bankEnabled} checked={method==='bank_transfer'} onChange={()=>setMethod('bank_transfer')}/><span><strong className="block text-sm">Chuyển khoản</strong><span className="mt-1 block text-xs leading-5">{bankEnabled?'Báo chuyển khoản sau khi có mã đơn':'Chưa kích hoạt tại hệ thống'}</span></span></label></div></fieldset>{method==='bank_transfer'&&recipient&&<div className="mt-4 overflow-hidden rounded-2xl border border-[#D3E2F3] bg-gradient-to-br from-[#F0F6FF] to-white p-5 text-sm leading-7 text-[#172D55]"><p className="mb-3 text-xs font-black uppercase tracking-wider text-[#557194]">Thông tin chuyển khoản</p><div className="grid gap-x-4 gap-y-1 sm:grid-cols-[105px_1fr]"><span className="text-slate-500">Ngân hàng</span><strong>{recipient.accountNumber==='KHONG-CHUYEN-TIEN'?'PetDay Payment':recipient.bankName}</strong><span className="text-slate-500">Chủ tài khoản</span><strong>{recipient.accountHolder}</strong>{recipient.accountNumber!=='KHONG-CHUYEN-TIEN'&&<><span className="text-slate-500">Số tài khoản</span><strong className="break-all">{recipient.accountNumber}</strong></>}</div><p className="mt-3 rounded-xl bg-white/85 px-3 py-2 text-xs text-[#536A87]">Sau khi xác nhận đơn, nhập ngay ngân hàng và tên người chuyển vào biểu mẫu PetDay Payment. Admin sẽ xác nhận riêng.</p>{recipient.accountNumber==='KHONG-CHUYEN-TIEN'&&<p className="mt-2 text-xs font-bold text-[#A24B38]">Thanh toán thử nghiệm · không chuyển tiền thật hoặc quét QR ngân hàng.</p>}</div>}{(count>0||checkoutAttempted)&&checkoutBlockers.length>0&&<div id="petday-checkout-errors" role="alert" className="mt-4 rounded-xl border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-950"><p className="font-extrabold">Chưa thể xác nhận đơn hàng:</p><ul className="mt-2 list-disc space-y-1 pl-5">{checkoutBlockers.map((problem,i)=><li key={i}>{problem}</li>)}</ul><button type="button" onClick={load} className="mt-3 rounded-lg border border-amber-600 px-3 py-1.5 text-xs font-semibold">Cập nhật lại tồn kho</button></div>}{message&&<div role="status" className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">✓ {message} <button type="button" onClick={()=>document.getElementById('petday-purchase-history')?.scrollIntoView({behavior:'smooth',block:'start'})} className="ml-2 underline">Xem lịch sử mua</button></div>}{!count&&!message&&<p className="mt-4 text-sm text-slate-500">Hãy chọn sản phẩm ở phía trên để tạo đơn hàng.</p>}<button type="button" disabled={busy||count===0} onClick={place} aria-disabled={!canSubmit} className="mt-5 w-full rounded-xl bg-[#FF7666] px-6 py-3.5 font-extrabold text-white shadow-lg shadow-[#FF7666]/20 disabled:opacity-40">{busy?'Đang tạo đơn...':'Xác nhận đơn hàng • '+money(grandTotal)}</button><p className="mt-3 text-xs leading-5 text-slate-500">Thông tin giao tận nhà cần được nhân viên xác nhận. Giá và tồn kho được máy chủ xác nhận lại khi đặt. Có thể chọn nhiều loại hàng trong một đơn, mỗi loại tối đa 99 sản phẩm và không vượt tồn kho. Đơn giao tận nhà được tính phí ship theo khu vực và cần địa chỉ cụ thể.</p></div></div>
   <details id="petday-purchase-history" className="mt-7 scroll-mt-28 rounded-2xl border border-[#E3EAF4] p-5"><summary className="cursor-pointer font-extrabold text-[#172D55]">Lịch sử mua hàng ({orders.length})</summary><div className="mt-4 space-y-3">{orders.map(o=>{const fulfillmentMethod=o.fulfillmentMethod||o.fulfillment_method||'pickup';const zone=o.deliveryZone||o.delivery_zone;const address=o.deliveryAddress||o.delivery_address;const receiver=o.receiverName||o.receiver_name;const phone=o.receiverPhone||o.receiver_phone;return <div key={o.code} className="rounded-xl bg-[#F5F8FD] p-4 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><strong>{o.code}</strong><span>{money(o.total)} · {orderStatusVi[o.status]||o.status} · {(o.paymentStatus||o.payment_status)==='paid'?'Đã ghi nhận thanh toán':'Chưa thanh toán'}</span></div><p className="mt-1 text-slate-500">{o.branch} · {fulfillmentMethod==='delivery'?'Giao tận nhà':'Nhận tại cửa hàng'}{zone&&' · '+deliveryZoneMeta[zone as 'inner_hcm'|'outer_hcm']?.label}</p>{address&&<p className="mt-1 text-slate-500">{receiver||'Người nhận'} · {phone} · {address}</p>}{(o as Order & {delivery_eta?:string}).delivery_eta&&<p className="mt-1 font-semibold text-[#142B55]">Ngày giao dự kiến: {String((o as Order & {delivery_eta?:string}).delivery_eta).slice(0,10)}</p>}{(o.paymentMethod||o.payment_method)==='bank_transfer'&&(o.paymentStatus||o.payment_status)!=='paid'&&o.status!=='cancelled'&&<div className="mt-3 rounded-xl border border-[#D4E5FA] bg-white p-3"><p className="text-xs font-semibold text-[#142B55]">{transferNotices[o.code]?'Đã thông báo chuyển khoản · chờ xác nhận':'Đơn đang chờ thanh toán chuyển khoản'}</p>{!transferNotices[o.code]&&<button type="button" onClick={()=>setOpenTransfer(o.code)} className="mt-2 rounded-lg bg-[#172D55] px-4 py-2 text-xs font-bold text-white">Nhập thông tin chuyển khoản</button>}{transferNotices[o.code]&&<p className="mt-2 text-xs font-semibold text-[#405B82]">Thông tin đã gửi · chờ Admin xác nhận</p>}{openTransfer===o.code&&<TransferDetailsForm code={o.code} total={o.total} recipient={recipient} busy={reportBusy===o.code} onCancel={()=>setOpenTransfer(null)} onSubmit={info=>reportTransfer(o.code,info)} />}</div>}<p className="mt-1 text-slate-500">{o.items?.map(x=>x.name+' × '+x.quantity).join(', ')}</p>
{cancelRequests[o.code]&&<div className="mt-3 rounded-xl border border-[#DCE6F5] bg-white p-3"><strong>Yêu cầu hủy: {({pending:'Chờ Admin xem xét',approved:'Đã duyệt hủy',rejected:'Không chấp thuận'} as Record<string,string>)[cancelRequests[o.code].status]}</strong><p className="mt-1 text-xs">Lý do: {cancelRequests[o.code].reason}</p>{cancelRequests[o.code].adminNote&&<p className="mt-1 text-xs">Phản hồi: {cancelRequests[o.code].adminNote}</p>}{cancelRequests[o.code].status==='approved'&&(o.paymentStatus||o.payment_status)==='paid'&&<p className="mt-1 text-xs text-[#142B55]">Khoản hoàn được xét riêng trong mục Theo dõi hoàn tiền bên dưới.</p>}</div>}
{!cancelRequests[o.code]&&['pending','confirmed','ready'].includes(o.status)&&<div className="mt-3"><button type="button" className="rounded-xl border border-[#E9ADA8] px-4 py-2 text-xs font-bold text-[#B34539]" onClick={()=>setCancelOpen(cancelOpen===o.code?null:o.code)}>Yêu cầu hủy đơn</button>{cancelOpen===o.code&&<div className="mt-2 rounded-xl border bg-white p-3"><label className="block text-xs font-bold">Lý do hủy<textarea className="mt-2 w-full rounded-xl border p-3" rows={2} maxLength={800} value={cancelReason[o.code]||''} onChange={e=>setCancelReason(v=>({...v,[o.code]:e.target.value}))} placeholder="Ví dụ: Tôi muốn hủy trước khi nhận hàng..."/></label><p className="my-2 text-xs text-slate-500">Nếu đơn đã thanh toán, Admin sẽ xem xét khoản hoàn tiền riêng sau khi duyệt hủy.</p><button type="button" disabled={busy||(cancelReason[o.code]||'').trim().length<10} className="rounded-xl bg-[#142B55] px-4 py-2 text-xs font-bold text-white disabled:opacity-50" onClick={()=>sendCancel(o.code)}>Gửi yêu cầu hủy</button></div>}</div>}
</div>})}{retailRefunds.length>0&&<div className="rounded-xl border border-[#DDE9F8] bg-white p-4"><strong className="text-[#142B55]">Theo dõi hoàn tiền cửa hàng</strong><div className="mt-2 space-y-2">{retailRefunds.map(r=><div key={r.id} className="rounded-xl bg-[#F1F6FC] p-3 text-xs"><strong>{r.code} · {money(r.amount)}</strong><p className="mt-1 text-slate-600">Ngày đặt: {r.orderCreatedAt?new Date(r.orderCreatedAt).toLocaleString('vi-VN'):'—'} · Ngày lập hồ sơ: {r.createdAt?new Date(r.createdAt).toLocaleString('vi-VN'):'—'}</p><p className="text-slate-600">Ngày xác nhận hoàn: {r.completedAt?new Date(r.completedAt).toLocaleString('vi-VN'):'Chưa hoàn tất'}</p><p>{({pending:'Chờ duyệt hoàn',approved:'Đã duyệt – chờ hoàn tiền',rejected:'Không hoàn tiền',completed:'Đã ghi nhận hoàn tiền'} as Record<string,string>)[r.status]||r.status}</p>{r.adminNote&&<p>Ghi chú: {r.adminNote}</p>}</div>)}</div></div>}{orders.length===0&&<p className="text-sm text-slate-500">Chưa có đơn mua hàng riêng.</p>}</div></details>
  </div></section>;
}
export function AdminStandaloneOrders({token}:{token:string}){
 const [cancelRequestsAdmin,setCancelRequestsAdmin]=useState<any[]>([]),[cancelNotesAdmin,setCancelNotesAdmin]=useState<Record<number,string>>({});const [orders,setOrders]=useState<Order[]>([]),[etas,setEtas]=useState<Record<string,string>>({});
 const [exceptionNotes,setExceptionNotes]=useState<Record<string,string>>({}),[exceptionDates,setExceptionDates]=useState<Record<string,string>>({}),[returnStock,setReturnStock]=useState<Record<string,boolean>>({});
 const [filter,setFilter]=useState('all'),[error,setError]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[demo,setDemo]=useState(false),[notices,setNotices]=useState<Record<string,{senderBank?:string;senderName?:string;customerReference?:string}>>({});
 const load=async()=>{try{const [data,options]=await Promise.all([request('/admin/retail/orders',token),request('/payment/options',token)]);setOrders(data);const cr=await request('/admin/retail/cancellation-requests',token).catch(()=>[]);setCancelRequestsAdmin(Array.isArray(cr)?cr:[]);setDemo(Boolean(options?.bankTransfer?.demo));const ns=await request('/admin/retail-transfer-notices',token).catch(()=>[]);setNotices(Object.fromEntries((Array.isArray(ns)?ns:[]).map((n:{code:string;senderBank?:string;senderName?:string;customerReference?:string})=>[n.code,n])))}catch(e){setError(String(e))}};
 useEffect(()=>{load()},[token]);
 async function update(code:string,changes:object){setBusy(true);setError('');setMessage('');try{await request('/admin/retail/orders/'+encodeURIComponent(code),token,'PATCH',changes);setMessage('Đã lưu thao tác vào PostgreSQL và nhật ký đơn hàng.');await load()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
 async function decideCancel(id:number,decision:'approved'|'rejected'){const note=(cancelNotesAdmin[id]||'').trim();if(note.length<8){setError('Vui lòng nhập ghi chú quyết định ít nhất 8 ký tự.');return;}if(!window.confirm(decision==='approved'?'Duyệt hủy đơn? Nếu đã thanh toán sẽ tạo hồ sơ hoàn tiền chờ xét.':'Từ chối yêu cầu hủy đơn?'))return;setBusy(true);setError('');setMessage('');try{await request('/admin/retail/cancellation-requests/'+id,token,'PATCH',{decision,note});setMessage('Đã xử lý yêu cầu hủy; khách sẽ thấy kết quả trong lịch sử mua hàng.');await load()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
 async function deliveryAction(code:string,action:'failed'|'retry'|'return_pending'|'returned'){
  const reason=(exceptionNotes[code]||'').trim();if(reason.length<8){setError('Nhập lý do giao hàng/hoàn hàng ít nhất 8 ký tự.');return;}
  if(action==='returned'&&!window.confirm('Đã nhận lại và kiểm tra hàng thực tế? Chỉ nhập lại kho nếu hàng đủ điều kiện bán.'))return;
  setBusy(true);setError('');setMessage('');try{await request('/admin/retail/orders/'+encodeURIComponent(code)+'/exception',token,'POST',{action,reason,...(action==='retry'?{deliveryEta:exceptionDates[code]}:{}),...(action==='returned'?{restockApproved:Boolean(returnStock[code])}:{})});setMessage('Đã lưu xử lý phát sinh và thông báo cho khách. Thanh toán/hoàn tiền được xử lý riêng.');await load()}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}
 }
 const states:Record<string,string>={pending:'Chờ xác nhận',confirmed:'Đã xác nhận',ready:'Sẵn sàng bàn giao',shipping:'Đang giao hàng',delivery_failed:'Giao thất bại',return_pending:'Chờ hàng hoàn',returned:'Đã nhận hàng hoàn',completed:'Hoàn tất',cancelled:'Đã hủy'};
 const visible=orders.filter(o=>filter==='all'||o.status===filter);
 return <section id="admin-shop-orders" className={panel}>
  <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-[#FF765E]">CỬA HÀNG PETDAY</p><h2 className="mt-1 text-xl font-black text-[#142B55]">Quản lý đơn hàng</h2><p className="mt-1 text-sm text-slate-600">Luồng đơn hàng riêng biệt với lịch dịch vụ. Xử lý nhận tại quầy hoặc giao tận nhà; thanh toán được xác nhận độc lập.</p></div><button type="button" className="rounded-xl border px-4 py-2 text-sm" onClick={load}>Làm mới</button></div>
  <p className="mt-3 rounded-xl bg-[#F1F6FD] px-4 py-3 text-xs leading-6 text-[#142B55]">Giao tận nhà: <strong>Chờ xác nhận → Đã xác nhận → Đóng gói → Đang giao → Giao thành công</strong>. Nhận tại cửa hàng: <strong>Chờ xác nhận → Đã xác nhận → Sẵn sàng nhận → Đã nhận</strong>. Ghi nhận thanh toán riêng, không tự chuyển trạng thái giao hàng.</p>
  
  {error&&<p role="alert" className="mt-3 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}{message&&<p role="status" className="mt-3 rounded-xl bg-blue-50 p-3 text-sm text-[#142B55]">{message}</p>}
  <div className="mt-5 rounded-2xl border border-[#DCE6F5] bg-[#F7FAFF] p-4"><h3 className="text-base font-extrabold text-[#142B55]">Yêu cầu hủy đơn từ khách ({cancelRequestsAdmin.filter(x=>x.status==='pending').length} chờ)</h3><p className="mt-1 text-xs text-slate-600">Duyệt hủy và xét hoàn tiền là hai thao tác riêng; khoản đã thu không bị xóa.</p><div className="mt-3 space-y-3">{cancelRequestsAdmin.filter(x=>x.status==='pending').map(x=><article key={x.id} className="rounded-xl border bg-white p-4"><div className="flex flex-wrap justify-between gap-2"><strong>{x.code} · {x.customerName}</strong><span className="text-sm">{money(x.total)} · {x.paymentStatus==='paid'?'Đã thu tiền':'Chưa thu tiền'}</span></div><p className="mt-2 text-sm">Lý do khách: {x.reason}</p><p className="mt-1 text-xs text-slate-500">Đơn: {orderStatusVi[x.orderStatus]||x.orderStatus}</p><textarea className="mt-3 w-full rounded-xl border p-3 text-sm" rows={2} maxLength={800} placeholder="Ghi lý do quyết định (ít nhất 8 ký tự)" value={cancelNotesAdmin[x.id]||''} onChange={e=>setCancelNotesAdmin(v=>({...v,[x.id]:e.target.value}))}/><div className="mt-2 flex gap-2"><button disabled={busy} onClick={()=>decideCancel(x.id,'approved')} className="rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white disabled:opacity-50">Chấp thuận hủy</button><button disabled={busy} onClick={()=>decideCancel(x.id,'rejected')} className="rounded-xl border px-4 py-2 text-sm font-bold disabled:opacity-50">Từ chối</button></div></article>)}{!cancelRequestsAdmin.some(x=>x.status==='pending')&&<p className="text-sm text-slate-500">Không có yêu cầu hủy đơn đang chờ.</p>}</div></div>
  <div className="mt-4 flex flex-wrap items-center gap-2"><label className="text-sm font-semibold">Lọc trạng thái:</label><select className="rounded-xl border px-3 py-2 text-sm" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Tất cả ({orders.length})</option>{Object.entries(states).map(([key,value])=><option key={key} value={key}>{value}</option>)}</select></div>
  <div className="mt-4 grid gap-4 lg:grid-cols-2">{visible.map(o=>{const mode=o.fulfillmentMethod||o.fulfillment_method||'pickup';const paid=(o.payment_status||o.paymentStatus)==='paid';const method=o.payment_method||o.paymentMethod||'cash';const zone=o.deliveryZone||o.delivery_zone;const eta=(o as Order & {delivery_eta?:string}).delivery_eta;return <article key={o.code} className="rounded-2xl border border-[#E0E8F4] bg-[#FCFDFF] p-4">
   <div className="flex flex-wrap justify-between gap-2"><div><strong className="text-[#142B55]">{o.code}</strong><p className="mt-1 text-xs text-slate-500">{o.branch}</p></div><strong>{money(o.total)}</strong></div>
   <div className="mt-3 flex flex-wrap gap-2 text-xs"><span className="rounded-full bg-[#EAF2FD] px-3 py-1 font-bold">{states[o.status]||o.status}</span><span className={'rounded-full px-3 py-1 font-bold '+(paid?'bg-emerald-50 text-emerald-800':'bg-amber-50 text-amber-800')}>{paid?'Đã thanh toán':'Chưa thanh toán'}</span><span className="rounded-full bg-white px-3 py-1">{mode==='delivery'?'Giao tận nhà':'Nhận tại cửa hàng'}</span></div>
   <p className="mt-3 text-sm">Phương thức: <strong>{method==='bank_transfer'?'Chuyển khoản':'Tiền mặt'}</strong></p>{method==='bank_transfer'&&!paid&&notices[o.code]&&<p className="mt-2 rounded-xl border border-[#D5E3F5] bg-[#EDF5FF] p-3 text-xs font-semibold text-[#142B55]">Khách đã báo chuyển khoản · đang chờ xác nhận<br/>Người chuyển: {notices[o.code].senderName||'Chưa cung cấp'} · {notices[o.code].senderBank||'Chưa chọn ngân hàng'} · Mã tham chiếu: {notices[o.code].customerReference||'Không có'}</p>}
   {mode==='delivery'&&<div className="mt-2 rounded-xl bg-[#F0F6FC] p-3 text-xs text-slate-600"><p>Người nhận: {o.receiver_name||o.receiverName} · {o.receiver_phone||o.receiverPhone}</p><p className="mt-1">{o.delivery_address||o.deliveryAddress}</p><p className="mt-1">Khu vực: {zone&&deliveryZoneMeta[zone as 'inner_hcm'|'outer_hcm']?.label}</p>{eta&&<p className="mt-1 font-bold text-[#142B55]">Dự kiến giao: {String(eta).slice(0,10)}</p>}</div>}
   {!paid&&o.status!=='cancelled'&&<p className="mt-3 rounded-xl border border-[#D7E5F8] bg-[#F1F6FE] p-3 text-xs font-semibold text-[#142B55]">Chưa ghi nhận thanh toán. Vào <strong>Admin → Tài chính → Cửa hàng</strong> để xác nhận tại một nơi. Trạng thái giao nhận vẫn được quản lý ở đây.</p>}
   <div className="mt-4 flex flex-wrap gap-2">{o.status==='pending'&&<button className="rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white" disabled={busy} onClick={()=>update(o.code,{status:'confirmed'})}>Xác nhận đơn</button>}{o.status==='confirmed'&&<button className="rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white" disabled={busy} onClick={()=>update(o.code,{status:'ready'})}>{mode==='delivery'?'Đã đóng gói · Chờ giao':'Sẵn sàng nhận tại quầy'}</button>}
   {mode==='delivery'&&o.status==='ready'&&<div className="w-full rounded-xl border p-3"><label className="text-xs font-bold">Ngày dự kiến giao đến khách<input aria-label={'Ngày giao '+o.code} type="date" className="mt-2 w-full rounded-lg border px-3 py-2" min={new Date().toLocaleDateString('en-CA')} value={etas[o.code]||String(eta||'').slice(0,10)} onChange={e=>setEtas(v=>({...v,[o.code]:e.target.value}))}/></label><button type="button" disabled={busy||!(etas[o.code]||eta)} className="mt-2 w-full rounded-xl bg-[#142B55] p-2.5 text-sm font-bold text-white disabled:opacity-40" onClick={()=>update(o.code,{status:'shipping',deliveryEta:etas[o.code]||String(eta).slice(0,10)})}>Xác nhận đã bàn giao vận chuyển → Đang giao</button></div>}
   {mode==='delivery'&&o.status==='shipping'&&<p className="w-full rounded-xl bg-blue-50 px-3 py-2 text-xs font-semibold text-[#142B55]">Đơn đang giao. Chỉ xác nhận giao thành công sau khi người nhận đã nhận hàng; nếu thu tiền mặt, xác nhận đã thu tiền trước.</p>}{((mode==='delivery'&&o.status==='shipping')||(mode==='pickup'&&o.status==='ready'))&&<button disabled={busy||!paid} title={!paid?'Cần xác nhận thanh toán trước khi hoàn tất':undefined} className="rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white disabled:opacity-40" onClick={()=>update(o.code,{status:'completed'})}>{mode==='delivery'?'Xác nhận giao thành công':'Xác nhận khách đã nhận tại quầy'}</button>}
   {mode==='delivery'&&['shipping','delivery_failed','return_pending'].includes(o.status)&&<div className="w-full rounded-2xl border border-[#D6E2F3] bg-[#F6F9FE] p-3 space-y-3"><strong className="block text-sm text-[#142B55]">Xử lý giao hàng phát sinh</strong><label className="block text-xs font-semibold">Lý do / nội dung liên hệ với khách<textarea rows={2} maxLength={500} className="mt-1 w-full rounded-xl border p-2 text-sm" placeholder="Ví dụ: Khách từ chối nhận; đã gọi xác minh..." value={exceptionNotes[o.code]||''} onChange={e=>setExceptionNotes(v=>({...v,[o.code]:e.target.value}))}/></label>{o.status==='shipping'&&<button disabled={busy} onClick={()=>deliveryAction(o.code,'failed')} className="rounded-xl bg-orange-100 px-4 py-2 text-sm font-bold text-orange-900">Ghi nhận giao thất bại</button>}{o.status==='delivery_failed'&&<div className="grid gap-3 sm:grid-cols-2"><div><label className="block text-xs">Ngày giao lại<input className="mt-1 w-full rounded-xl border p-2" type="date" value={exceptionDates[o.code]||''} onChange={e=>setExceptionDates(v=>({...v,[o.code]:e.target.value}))}/></label><button className="mt-2 rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white disabled:opacity-40" disabled={busy||!exceptionDates[o.code]} onClick={()=>deliveryAction(o.code,'retry')}>Giao lại</button></div><button className="self-end rounded-xl border border-[#142B55] p-2 text-sm font-bold" disabled={busy} onClick={()=>deliveryAction(o.code,'return_pending')}>Ngừng giao · Chờ hàng hoàn</button></div>}{o.status==='return_pending'&&<><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={Boolean(returnStock[o.code])} onChange={e=>setReturnStock(v=>({...v,[o.code]:e.target.checked}))}/>Hàng đã kiểm tra và đủ điều kiện nhập lại kho</label><button disabled={busy} onClick={()=>deliveryAction(o.code,'returned')} className="rounded-xl bg-[#142B55] px-4 py-2 text-sm font-bold text-white">Xác nhận đã nhận hàng hoàn</button></>}{paid&&<p className="text-xs text-slate-600">Đã ghi nhận thanh toán: hoàn tiền phải được duyệt riêng tại Tài chính, không tự hoàn.</p>}</div>}{o.status==='returned'&&<p className="w-full rounded-xl border border-[#DDE9F8] bg-[#F2F7FC] p-3 text-xs">Đã nhận hàng hoàn. {paid?'Vào Tài chính → Hoàn tiền để xét khoản hoàn.':'Đơn chưa thu tiền, không phát sinh khoản hoàn.'}</p>}
   {!paid&&['pending','confirmed','ready'].includes(o.status)&&<button type="button" disabled={busy} className="rounded-xl border border-rose-300 px-3 py-2 text-sm text-rose-700" onClick={()=>{if(window.confirm('Hủy đơn chưa thanh toán và hoàn trả tồn kho?'))update(o.code,{status:'cancelled'})}}>Hủy đơn</button>}</div>
  </article>})}{visible.length===0&&<p className="col-span-full rounded-xl bg-[#F5F8FC] p-6 text-sm text-slate-500">Chưa có đơn thuộc trạng thái này.</p>}</div>
  <p className="mt-4 text-xs text-slate-500">Lịch sử đơn mua được lưu ở PostgreSQL và khách có thể xem tại Cửa hàng → Lịch sử mua. Đơn giao tận nhà dùng trạng thái “Đang giao”; cần chạy migration 039 trước khi sử dụng chức năng này.</p>
 </section>;
}
